{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_015EBFnEbcWQ6aFM1Ryt44Ux","type":"tool_result","content":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>\n<path>packages/esm-patient-chart-app/src/visit/dedupe-diagnoses.ts</path>\n<url>undefined</url>\n<content>\n1: import { type Diagnosis } from '@openmrs/esm-framework';\n2: \n3: /**\n4:  * A display-level aggregate of one diagnosis (keyed by concept UUID, or exact text for\n5:  * non-coded diagnoses) across the encounters of a visit. The `uuid`, `display`, and\n6:  * `diagnosis` reference come from one contributing encounter diagnosis so the entry has\n7:  * a stable key, but `rank` and `certainty` are aggregated across all duplicates and may\n8:  * not match that record. It must not be treated as an encounter diagnosis.\n9:  */\n10: export interface DedupedDiagnosis {\n11:   uuid: string;\n12:   display?: string;\n13:   diagnosis?: Diagnosis['diagnosis'];\n14:   rank?: number;\n15:   // Deliberately `string`, not the CONFIRMED/PROVISIONAL union: this is a display-level\n16:   // passthrough of whatever other writers stored, which may lie outside the known enum.\n17:   certainty?: string;\n18: }\n19: \n20: /**\n21:  * Collapses repeats of the same diagnosis recorded across multiple encounters of a visit\n22:  * into a single entry and sorts the result by rank (primary first). Duplicates are merged\n23:  * with: rank = the minimum across duplicates (primary if primary in any encounter), and\n24:  * certainty = the strongest across duplicates (CONFIRMED if confirmed in any encounter).\n25:  * Both rules are independent of encounter order.\n26:  */\n27: export function dedupeDiagnoses(diagnoses: Array<Diagnosis>): Array<DedupedDiagnosis> {\n28:   const merged = new Map<string, DedupedDiagnosis>();\n29:   const result: Array<DedupedDiagnosis> = [];\n30: \n31:   for (const { uuid, display, diagnosis, rank, certainty } of diagnoses) {\n32:     const key = diagnosis?.coded?.uuid ?? diagnosis?.nonCoded;\n33:     const existing = key ? merged.get(key) : undefined;\n34: \n35:     if (!existing) {\n36:       const entry: DedupedDiagnosis = { uuid, display, diagnosis, rank, certainty };\n37:       if (key) {\n38:         merged.set(key, entry);\n39:       }\n40:       result.push(entry);\n41:     } else {\n42:       existing.rank = minRank(existing.rank, rank);\n43:       existing.certainty = strongerCertainty(existing.certainty, certainty);\n44:     }\n45:   }\n46: \n47:   return result.sort((a, b) => (a.rank ?? Number.MAX_SAFE_INTEGER) - (b.rank ?? Number.MAX_SAFE_INTEGER));\n48: }\n49: \n50: function minRank(a: number | undefined, b: number | undefined): number | undefined {\n51:   if (a == null) {\n52:     return b;\n53:   }\n54:   if (b == null) {\n55:     return a;\n56:   }\n57:   return Math.min(a, b);\n58: }\n59: \n60: /**\n61:  * Deterministic certainty precedence: CONFIRMED > PROVISIONAL > any other stored value >\n62:  * unset. Values of equal precedence (two out-of-enum values from other writers) tie-break\n63:  * lexicographically, so the merge result never depends on encounter order.\n64:  */\n65: function strongerCertainty(a: string | undefined, b: string | undefined): string | undefined {\n66:   const precedence = (value: string | undefined) =>\n67:     value === 'CONFIRMED' ? 3 : value === 'PROVISIONAL' ? 2 : value != null ? 1 : 0;\n68:   if (precedence(a) !== precedence(b)) {\n69:     return precedence(a) > precedence(b) ? a : b;\n70:   }\n71:   if (a != null && b != null) {\n72:     return a <= b ? a : b;\n73:   }\n74:   return a ?? b;\n75: }\n76: \n\n(End of file - 76 lines total)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"8e7ccdb4-8b41-4c24-93b0-cf0c88cf3c9a","uuid":"69873273-224b-43c5-8913-54fc618b364e","timestamp":"2026-10-24T04:03:12.517Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>\n<path>packages/esm-patient-chart-app/src/visit/dedupe-